import lombok.Data;
import org.bson.types.ObjectId;
import org.springframework.data.annotation.Id;
import org.springframework.data.mongodb.core.mapping.Document;

@Data
@Document(collection = "journal_entries")
public class JournalEntry {
    @Id private ObjectId id;
    private String title;
    private String content;
}

import org.bson.types.ObjectId;
import org.springframework.data.mongodb.repository.MongoRepository;
import java.util.List;

public interface JournalEntryRepository
        extends MongoRepository<JournalEntry, ObjectId> {
    List<JournalEntry> findByTitle(String title);
}

import java.util.Optional;

JournalEntry entry = new JournalEntry();
entry.setTitle("Learning Spring");
JournalEntry saved = repository.save(entry);
Optional<JournalEntry> found = repository.findById(saved.getId());
